export function marketRecord(row,db) {
  if (!row || typeof row !== 'object') return null;
  if(!Number.isSafeInteger(row.id)||!Number.isSafeInteger(row.itemId)||!Number.isFinite(row.price)||row.price<0||!Number.isFinite(row.quantity)||row.quantity<=0)return null;
  const name=id=>{const info=db?.getItemInfo?.(id);const value=info?.identifiedDisplayName||info?.identifiedDiSPlayName||info?.displayName;return value&&value!=='Unknown Item'?value:`物品 #${id}`;};
  if (!Array.isArray(row.options || []) || !Array.isArray(row.cards || []) || !row.mapName) return null;
  const options=(row.options || []).filter(o=>o&&typeof o==='object').map(o=>String(o.display || `词条 ${o.type}：${o.value} (${o.param})`));
  return {id:`ltsd:${row.id}`,source:'ltsd',itemId:String(row.itemId),itemName:name(row.itemId),
    price:row.price,quantity:row.quantity,refine:row.upgrade || 0,cards:(row.cards || []).filter(Number).map(name),
    cardIds:row.cards || [],options,randomOptions:options,shop:String(row.title || row.vendorName || '未命名商店'),
    shopId:'',vendorName:row.vendorName,map:String(row.mapName || '').replace(/\.gat$/,'')+'.gat',
    x:Number.isFinite(row.x)?row.x:null,y:Number.isFinite(row.y)?row.y:null,
    lastSeenAt:new Date(Number.isFinite(Number(row.lastChangedAt)) && Number(row.lastChangedAt)>0 && Number(row.lastChangedAt)<8640000000000000 ? Number(row.lastChangedAt) : Date.now()).toISOString(),apiListingId:row.id,availability:'active'};
}

const textKey=value=>String(value||'').normalize('NFKC').replace(/\^[0-9a-f]{6}/gi,'').trim().toLocaleLowerCase();
function readMarketItemTable(app) {
  const db=app.getAmdModule('DB/DBManager');
  const tables=[db?.ItemInfo,app.getAmdModule('DB/Items/ItemTable')];
  const result={};
  for(const table of tables)for(const [id,item]of Object.entries(table||{})) {
    if(!/^\d+$/.test(id)||Number(id)<=0)continue;
    // Legacy ItemInfo names are decoded lazily by this native getter.
    let info=item;try{info=db?.getItemInfo?.(Number(id))||item;}catch { /* Ignore unavailable optional cached/native data. */ }
    const name=info?.identifiedDisplayName||info?.identifiedDiSPlayName||info?.displayName||item?.name;
    if(name&&name!=='Unknown Item')result[id]={identifiedDisplayName:name};
  }
  return result;
}
export function marketItemIds(query,table={}) {
  const key=textKey(query);if(!key)return [];
  if(/^\d+$/.test(key))return [Number(key)];
  const exact=[],partial=[];
  for(const [id,item] of Object.entries(table||{})) {
    const name=textKey(item?.identifiedDisplayName||item?.identifiedDiSPlayName||item?.displayName||item?.name);
    if(name===key)exact.push(Number(id));else if(name.includes(key))partial.push(Number(id));
  }
  return [...exact,...partial].filter(id=>Number.isSafeInteger(id)&&id>0);
}
export function marketQueryIds(query,table) {
  const terms=textKey(query).split(/\s+/).filter(Boolean);
  return [...new Set(terms.flatMap(term=>marketItemIds(term,table)))];
}
export function marketOptionFilters(query) {
  const terms=textKey(query).split(/\s+/).filter(Boolean),filters=[];
  for(const option of OPTION_CATALOG){
    if(!terms.some(term=>textKey(option.text).includes(term)))continue;
    if(option.flag&&option.operators.includes('eq'))filters.push(`${option.type}:eq:0`);
    else if(option.operators.includes('eq')&&option.operators.includes('neq'))filters.push(`${option.type}:eq:0`,`${option.type}:neq:0`);
  }
  const groups=[];for(let i=0;i<filters.length;i+=8)groups.push(filters.slice(i,i+8));return groups;
}
function matchFields(record){return [textKey(record.itemName),textKey([...(record.cards||[]),...(record.options||[]),...(record.randomOptions||[])].join(' ')),textKey(record.shop)];}
export function matchesMarketTerms(record,query) {
  const terms=textKey(query).split(/\s+/).filter(Boolean);
  const fields=[...(terms.length>1?matchFields(record).slice(0,2):matchFields(record)),textKey(record.itemId)];
  return terms.every(term=>fields.some(field=>field.includes(term)));
}
export function sortMarketRecords(records,sort,query,wanted=()=>false) {
  const key=textKey(query);
  const score=r=>{const terms=key.split(/\s+/).filter(Boolean);if(!terms.length)return 0;const fields=matchFields(r);const ranks=terms.map(term=>fields.findIndex(field=>field.includes(term)));return (Math.max(...ranks.map(rank=>rank<0?3:rank))*10+ranks.reduce((sum,rank)=>sum+Math.max(rank,0),0))*100+(fields[0]===key?0:fields[0].startsWith(key)?1:2);};
  return [...records].sort((a,b)=> {
    if(!!wanted(a)!==!!wanted(b))return wanted(a)?-1:1;
    const price=a.price-b.price;
    if(sort==='name')return a.itemName.localeCompare(b.itemName,'zh-CN')||price;
    if(sort==='relevance')return score(a)-score(b)||price;
    if(sort==='recent')return new Date(b.lastSeenAt)-new Date(a.lastSeenAt)||price;
    return sort==='price-desc'?-price:price;
  });
}

